CREATE     PROCEDURE [synapse_fo].[usp_Update_CUSTPAYMMODETABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:34
	Description: Update stored procedure for CUSTPAYMMODETABLE from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTTYPE] = stg.[ACCOUNTTYPE],
		tgt.[BANKCLIENTCLASSID_RU] = stg.[BANKCLIENTCLASSID_RU],
		tgt.[BANKCLIENTDOCUMENTTYPEID_RU] = stg.[BANKCLIENTDOCUMENTTYPEID_RU],
		tgt.[BANKCUSTPAYMIDTABLE] = stg.[BANKCUSTPAYMIDTABLE],
		tgt.[BANKTRANSTYPE] = stg.[BANKTRANSTYPE],
		tgt.[CATEGORYPURPOSE_W] = stg.[CATEGORYPURPOSE_W],
		tgt.[CHARGEBEARER_W] = stg.[CHARGEBEARER_W],
		tgt.[CLASSID] = stg.[CLASSID],
		tgt.[CLASSIDFILEANALYZE] = stg.[CLASSIDFILEANALYZE],
		tgt.[CLASSIDIN] = stg.[CLASSIDIN],
		tgt.[CLASSIDREMITTANCE] = stg.[CLASSIDREMITTANCE],
		tgt.[CLASSIDRETURN] = stg.[CLASSIDRETURN],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DESCPRIMARYMETHOD_BR] = stg.[DESCPRIMARYMETHOD_BR],
		tgt.[DIMCTRL] = stg.[DIMCTRL],
		tgt.[DIMENSIONATTRIBUTESET] = stg.[DIMENSIONATTRIBUTESET],
		--tgt.[DIMUSE] = stg.[DIMUSE],
		--tgt.[DIMUSE2_] = stg.[DIMUSE2_],
		--tgt.[DIMUSE3_] = stg.[DIMUSE3_],
		tgt.[DIRECTDEBIT] = stg.[DIRECTDEBIT],
		tgt.[DISCGRACEDAYS] = stg.[DISCGRACEDAYS],
		tgt.[ERFORMATMAPPINGID] = stg.[ERFORMATMAPPINGID],
		tgt.[ERMODELMAPPINGTABLE] = stg.[ERMODELMAPPINGTABLE],
		tgt.[EXPORTLAYOUTGROUPID_BR] = stg.[EXPORTLAYOUTGROUPID_BR],
		tgt.[EXPORTONINVOICE] = stg.[EXPORTONINVOICE],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FURTHERPOSTING] = stg.[FURTHERPOSTING],
		tgt.[INTERCOMPANYLEDGERDIMENSION] = stg.[INTERCOMPANYLEDGERDIMENSION],
		tgt.[ISSEPA] = stg.[ISSEPA],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LASTSEQUENCENUMBER] = stg.[LASTSEQUENCENUMBER],
		tgt.[LASTSEQUENCENUMDATE] = stg.[LASTSEQUENCENUMDATE],
		tgt.[LASTSEQUENCENUMTODAY] = stg.[LASTSEQUENCENUMTODAY],
		tgt.[LOCALINSTRUMENT_W] = stg.[LOCALINSTRUMENT_W],
		--tgt.[LSN] = stg.[LSN],
		tgt.[NAME] = stg.[NAME],
		tgt.[NUMBERSEQUENCETABLE_LT] = stg.[NUMBERSEQUENCETABLE_LT],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PAYMENTLEDGERDIMENSION] = stg.[PAYMENTLEDGERDIMENSION],
		tgt.[PAYMENTMETHOD_BR] = stg.[PAYMENTMETHOD_BR],
		tgt.[PAYMENTTYPE] = stg.[PAYMENTTYPE],
		tgt.[PAYMENTTYPE_MX] = stg.[PAYMENTTYPE_MX],
		tgt.[PAYMJOURNALNAMEID] = stg.[PAYMJOURNALNAMEID],
		tgt.[PAYMMODE] = stg.[PAYMMODE],
		tgt.[PAYMONINVOICE] = stg.[PAYMONINVOICE],
		tgt.[PAYMSTATUS] = stg.[PAYMSTATUS],
		tgt.[PAYMSUMBY] = stg.[PAYMSUMBY],
		tgt.[PDCCLEARINGPOSTING] = stg.[PDCCLEARINGPOSTING],
		tgt.[POSTINGPROFILEBILLSREMITCOLLECTION_IT] = stg.[POSTINGPROFILEBILLSREMITCOLLECTION_IT],
		tgt.[POSTINGPROFILEBILLSREMITDISCOUNT_IT] = stg.[POSTINGPROFILEBILLSREMITDISCOUNT_IT],
		tgt.[PRIMARYMETHOD_BR] = stg.[PRIMARYMETHOD_BR],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[RETURNLAYOUTGROUPID_BR] = stg.[RETURNLAYOUTGROUPID_BR],
		tgt.[SERVICELEVEL_W] = stg.[SERVICELEVEL_W],
		--tgt.[SKS_CNP_FORMATID] = stg.[SKS_CNP_FORMATID],
		--tgt.[SKS_CNP_PAYMMODE] = stg.[SKS_CNP_PAYMMODE],
		--tgt.[SKS_EFT_FORMATID] = stg.[SKS_EFT_FORMATID],
		--tgt.[SKS_EFT_PAYMMODE] = stg.[SKS_EFT_PAYMMODE],
		tgt.[SPLITPAYMENT_W] = stg.[SPLITPAYMENT_W],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TYPEOFDRAFT] = stg.[TYPEOFDRAFT],
		tgt.[USECUSTOMFORMAT_RU] = stg.[USECUSTOMFORMAT_RU],
		tgt.[USEGERCONFIGURATION] = stg.[USEGERCONFIGURATION],
		tgt.[USEGERIMPORT] = stg.[USEGERIMPORT]
	 FROM [synapse_fo].[CUSTPAYMMODETABLE] tgt
		INNER JOIN [staging_fo].[CUSTPAYMMODETABLE] stg
			ON  stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[PaymMode] = tgt.[PaymMode] 
		
END
